// Decade counter, counts from 0 to 9, with a 10-stage per-stage delay.
// Same function as a Counter10_UP_D1_TRIG0 counter, just written out
// explicitly.
module TopModule(input clk, input reset, input slowena, output reg [3:0] q);
  reg [3:0] count;
  always @(posedge clk) begin
    if (reset) count <= 4'd0;
    else if (slowena) begin
      case (count)
        4'd0: count <= 4'd1;
        4'd1: count <= 4'd2;
        4'd2: count <= 4'd3;
        4'd3: count <= 4'd4;
        4'd4: count <= 4'd5;
        4'd5: count <= 4'd6;
        4'd6: count <= 4'd7;
        4'd7: count <= 4'd8;
        4'd8: count <= 4'd9;
        4'd9: count <= 4'd0;
      endcase
    end
  end
  assign q = count;
endmodule

